let ctx;
let lines = [];
let shapes = [];

let colors = ['#083d77', '#da4167', '#f4d35e', '#f78764', '#01baef', '#048a81'];

let centerX, centerY;
let minSize = 0;

let noiseFilter;

function setup() {
	createCanvas(600, 900);
	rectMode(CENTER);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	minSize = cellSize = (width * 0.8) / 25;
	INIT();

	background('#ebebd3');

	strokeWeight(width * 0.003);
	stroke('#000000');
	for (let c of shapes) {
		push();
		translate(c.x, c.y);
		fill(random(colors));
		if (c.n == 0) {
		} else if (c.n == 1) {
			drawPattern(0, 0, c.w, c.h, int(random(2)));
		} else if (c.n == 2) {
			noStroke();
			rect(0, 0, c.w, c.h);
		} else if (c.n == 3) {
			circle(0, 0, min(c.w, c.h) * random(0.75, 0.5));
		} else if (c.n == 4) {
			scale(1, random([-1, 1]));

			beginShape();
			vertex(0, (c.h / 2) - minSize);
			vertex(-(minSize / 2), (c.h / 2));
			vertex((minSize / 2), (c.h / 2));
			endShape(CLOSE);
		} else if (c.n == 5) {
			scale(random([-1, 1]), random([-1, 1]));
			square((c.w / 2) - min(c.w, c.h) * 0.25, (c.h / 2) - min(c.w, c.h) * 0.25, min(c.w, c.h) * 0.5);
		} else if (c.n == 6) {
			beginShape();
			vertex(c.w / 2, 0);
			vertex(0, c.h / 2);
			vertex(-c.w / 2, 0);
			vertex(0, -c.h / 2);
			endShape(CLOSE);
		} else if (c.n == 7) {
			noFill();
			beginShape();
			if (random() < 0.5) {
				vertex(c.w / 2, 0);
				vertex(-c.w / 2, 0);
			} else {
				vertex(0, -c.h / 2);
				vertex(0, c.h / 2);
			}
			endShape(CLOSE);
			fill(random(colors));
			circle(0, 0, minSize * 0.5);

		} else if (c.n == 8) {
			scale(random([-1, 1]), random([-1, 1]));

			if (random() < 0.5) {
				line(c.w * 0.5, c.h * 0.1, c.w * 0.5 - minSize * 0.25, c.h * 0.1);
				line(c.w * 0.5, -c.h * 0.1, c.w * 0.5 - minSize * 0.25, -c.h * 0.1);

			} else {

			}
		}
		pop();

	}

	stroke('#000000');
	for (let l of lines) {
		line(l.x1, l.y1, l.x2, l.y2);
	}

	noiseFilter = createImage(width, height);
	noiseFilter.loadPixels();
	let pix = noiseFilter.width * noiseFilter.height * 4;
	for (let i = 0; i < pix; i += 4) {
		let bw = random(100, 255);
		noiseFilter.pixels[i] = bw;
		noiseFilter.pixels[i + 1] = bw;
		noiseFilter.pixels[i + 2] = bw;
		noiseFilter.pixels[i + 3] = 25;
	}
	noiseFilter.updatePixels();

	image(noiseFilter, 0, 0);

}

