}

function INIT() {
	lines = [];
	shapes = [];
	let totalCells = 22;
	let totalRowCells = int(totalCells * 1.5);
	let totalColCells = totalCells;
	let rowCount = 0;
	let colCount = 0;
	let rowBoundaries = [0];
	let colBoundaries = [0];
	while (rowCount < totalRowCells) {
		let span = int(random(3) + 1);
		if (totalRowCells < (rowCount + span)) {
			span = totalRowCells - rowCount;
		} else { }
		rowCount += span;
		rowBoundaries.push(rowCount);
	}

	while (colCount < totalColCells) {
		let span = int(random(3) + 1);
		if (totalColCells < (colCount + span)) {
			span = totalColCells - colCount;
		} else { }
		colCount += span;
		colBoundaries.push(colCount);
	}

	let areaX = width * 0.8;
	let areaY = height * 0.8;
	let cellW = areaX / totalColCells;
	let cellH = areaY / totalRowCells;

	for (let i = 0; i < colBoundaries.length; i++) {
		let maxLineY = height * random(0.9, 1);
		let minLineY = height * random(0.1);
		let x = colBoundaries[i] * cellW + (width - areaX) / 2;
		lines.push({ x1: x, y1: minLineY, x2: x, y2: maxLineY });
	}

	for (let j = 0; j < rowBoundaries.length; j++) {
		let maxLineX = width * random(0.9, 1);
		let minLineX = width * random(0.1);
		let y = rowBoundaries[j] * cellH + (height - areaY) / 2;
		lines.push({ x1: minLineX, y1: y, x2: maxLineX, y2: y });
	}

	for (let i = 0; i < colBoundaries.length - 1; i++) {
		let w = (colBoundaries[i + 1] - colBoundaries[i]) * cellW;
		let x = colBoundaries[i] * cellW + (width - areaX) / 2 + w / 2;
		for (let j = 0; j < rowBoundaries.length - 1; j++) {
			let h = (rowBoundaries[j + 1] - rowBoundaries[j]) * cellH;
			let y = rowBoundaries[j] * cellH + (height - areaY) / 2 + h / 2;
			let n = int(random(9));
			shapes.push({ x: x, y: y, w: w, h: h, n: n });
		}
	}
}

function drawPattern(x, y, w, h, type) {
	/*
	0:Checkered, 1:Stripe
	*/
	let cellSize = minSize / 4;
	let color1 = '#ebebd3';
	let color2 = '#000000';
	let toggle = int(random(2));
	let pToggle = toggle;
	push();
	translate(x, y);
	noStroke();
	fill(color1);
	rect(0, 0, w, h);
	ctx.clip();
	if (type == 0) {
		for (let xx = 0; xx < w; xx += cellSize) {
			if (toggle == pToggle) {
				if (toggle) {
					toggle = 0;
				} else {
					toggle = 1;
				}
			}
			pToggle = toggle;
			for (let yy = 0; yy < h; yy += cellSize) {
				if (toggle) {
					fill(color2);
					square(xx - (w / 2) + cellSize / 2, yy - (h / 2) + cellSize / 2, cellSize);
					toggle = 0;
				} else {
					toggle = 1;
				}
			}
		}
	} else if (type == 1) {
		for (let xx = 0; xx < w; xx += cellSize) {
			if (toggle == pToggle) {
				if (toggle) {
					toggle = 0;
				} else {
					toggle = 1;
				}
			}
			pToggle = toggle;
			for (let yy = 0; yy < h; yy += cellSize) {
				fill(color2);
				beginShape();
				if (toggle) {
					vertex(xx - (w / 2), yy - (h / 2));
					vertex(xx - (w / 2) + cellSize, yy - (h / 2));
					vertex(xx - (w / 2), yy - (h / 2) + cellSize);
					toggle = 0;
				} else {
					vertex(xx - (w / 2) + cellSize, yy - (h / 2) + cellSize);
					vertex(xx - (w / 2) + cellSize, yy - (h / 2));
					vertex(xx - (w / 2), yy - (h / 2) + cellSize);
					toggle = 1;
				}
				endShape();
			}
		}
	}

	pop();
}

